1	package consensus
2	
3	import (
4		"reflect"
5		"testing"
6	)
7	
8	// 回归保障：满池时提交无效交易，拒绝原因必须反映交易本身的问题
9	// （bad-signature / tx-expired），不能被容量判断统一变成 pool-full；
10	// 更不能先挤出一笔合法交易再报告失败。场景复用 capProtectScene：
11	// 容量 6 恰好占满，lp/cp/shared 被未决候选引用等待投票，q1..q3 排队
12	// 可淘汰（q1 费用 50 最低）。新交易均来自 keys[4]（已确认序号 0、无待
13	// 处理交易），序号 1，费用 51 严格高于 q1，标识从未被节点接受——若通过
14	// 校验，按原有容量规则会获准入池并挤出 q1。
15	
16	// fullPoolRejectSnap 在拒绝后断言场景完全冻结：视图、条目、账户与提交前
17	// 一致，轮次不变，q1 没有任何淘汰记录，池仍恰好满。
18	func fullPoolRejectSnap(t *testing.T, s *capProtectScene,
19		beforeEntries map[string]capEntrySnap, beforeAccounts map[string]string,
20		beforeLocal ProposalView, beforeRC *RoundCandidates,
21	) {
22		t.Helper()
23		n := s.n
24		s.assertFrozenViews(t, beforeEntries, beforeAccounts, beforeLocal, beforeRC)
25		if got := n.CurrentRound(); got != 1 {
26			t.Fatalf("round = %d, rejected submit must not advance the round", got)
27		}
28		if got := n.st.poolSize(); got != 6 {
29			t.Fatalf("pool size = %d, want 6 (rejection must not free a slot)", got)
30		}
31		// q1 仍在账户待处理列表中：内容、序号与等待打包说明不变，没有新增淘汰记录。
32		info, err := n.Tx(s.q1.ID())
33		if err != nil {
34			t.Fatal(err)
35		}
36		if info.Status != StatusQueued || info.DropReason != "" || info.DropRound != 0 {
37			t.Fatalf("q1 after rejection = %+v, want untouched queued", info)
38		}
39		assertTxMatches(t, info.Tx, s.q1)
40		assertAccountQueue(t, n, s.keys[3].pub, 0, map[string]string{
41			s.q1.ID(): "waiting-pack", s.q2.ID(): "waiting-pack", s.q3.ID(): "waiting-pack",
42		})
43		// 新交易发送者的已确认序号保持 0，且没有留下任何待处理交易。
44		assertAccountQueue(t, n, s.keys[4].pub, 0, map[string]string{})
45	}
46	
47	// assertRejectedUnknown 断言提交以指定原因拒绝、不返回成功结果，
48	// 且按该交易标识查询得到 unknown-transaction（不留历史）。
49	func assertRejectedUnknown(t *testing.T, n *Node, tx *Transaction, wantReason string) {
50		t.Helper()
51		res, err := n.Submit(tx)
52		if reason(err) != wantReason {
53			t.Fatalf("submit got %v, want %s", err, wantReason)
54		}
55		if res != nil {
56			t.Fatalf("rejected submit returned result %+v, want nil", res)
57		}
58		if _, err := n.Tx(tx.ID()); reason(err) != ReasonUnknownTx {
59			t.Fatalf("rejected tx query = %v, want %s", err, ReasonUnknownTx)
60		}
61	}
62	
63	// assertValidSubmitEvictsQ1 在拒绝之后提交一笔签名有效、未到期的全新交易：
64	// 应正常入池并挤出 q1，受候选保护的交易继续保留。
65	func assertValidSubmitEvictsQ1(t *testing.T, s *capProtectScene, beforeLocal ProposalView, beforeRC *RoundCandidates) {
66		t.Helper()
67		n := s.n
68		win := NewTransaction(s.keys[4].priv, 1, []byte("valid-winner"), 51, 100)
69		res, err := n.Submit(win)
70		if err != nil {
71			t.Fatalf("valid higher-fee tx must be admitted after rejections: %v", err)
72		}
73		if res.TxID != win.ID() || res.EvictedID != s.q1.ID() || res.ReplacedID != "" {
74			t.Fatalf("submit result = %+v, want accept with evicted q1 and no replace link", res)
75		}
76		if info, _ := n.Tx(win.ID()); info.Status != StatusQueued {
77			t.Fatalf("new tx status = %s, want queued", info.Status)
78		}
79		if info, _ := n.Tx(s.q1.ID()); info.Status != StatusDropped || info.DropReason != DropReasonPoolCapacity || info.DropRound != 1 {
80			t.Fatalf("q1 after valid submit = %+v, want dropped/pool-capacity/round 1", info)
81		}
82		// 受候选保护的交易继续保留等待投票，候选视图不受淘汰影响。
83		for _, tx := range []*Transaction{s.lp, s.cp, s.shared} {
84			if info, _ := n.Tx(tx.ID()); info.Status != StatusProposed {
85				t.Fatalf("protected tx %s = %s, want proposed", tx.ID(), info.Status)
86			}
87		}
88		assertAccountQueue(t, n, s.keys[0].pub, 0, map[string]string{s.lp.ID(): "waiting-vote"})
89		assertAccountQueue(t, n, s.keys[1].pub, 0, map[string]string{s.cp.ID(): "waiting-vote"})
90		assertAccountQueue(t, n, s.keys[2].pub, 0, map[string]string{s.shared.ID(): "waiting-vote"})
91		if got := mustCandidates(t, n, 1); !reflect.DeepEqual(got, beforeRC) {
92			t.Fatalf("candidates changed by eviction:\nbefore=%+v\nafter =%+v", beforeRC, got)
93		}
94		if got, ok := n.Proposal(); !ok || !reflect.DeepEqual(got, beforeLocal) {
95			t.Fatalf("local proposal changed:\nbefore=%+v\nafter =%+v ok=%v", beforeLocal, got, ok)
96		}
97		if got := n.st.poolSize(); got != 6 {
98			t.Fatalf("pool size after eviction = %d, want 6", got)
99		}
100	}
101	
102	// 满池时签名与交易内容不匹配（公钥与签名长度均正确）必须返回 bad-signature，
103	// 而不是 pool-full；该交易同时已经到期时结果不变。拒绝不挤出任何交易，
104	// 之后合法交易仍按原有容量规则入池并挤出 q1。
105	func TestFullPoolRejectsBadSignature(t *testing.T) {
106		s := newCapProtectScene(t)
107		n := s.n
108		beforeEntries, beforeAccounts, beforeLocal, beforeRC := s.snapshots(t)
109	
110		// 签名长度正确但内容与签名不匹配；费用 51 本可挤出 q1。
111		badSig := NewTransaction(s.keys[4].priv, 1, []byte("bad-sig"), 51, 100)
112		badSig.Signature[0] ^= 0xff
113		if badSig.Verify() {
114			t.Fatal("test setup: tampered signature must not verify")
115		}
116		assertRejectedUnknown(t, n, badSig, ReasonBadSignature)
117	
118		// 同时已经到期（到期轮次等于当前轮次 1）的坏签名交易：仍返回 bad-signature。
119		badSigExpired := NewTransaction(s.keys[4].priv, 1, []byte("bad-sig-expired"), 51, 1)
120		badSigExpired.Signature[0] ^= 0xff
121		if badSigExpired.Verify() {
122			t.Fatal("test setup: tampered signature must not verify")
123		}
124		assertRejectedUnknown(t, n, badSigExpired, ReasonBadSignature)
125	
126		fullPoolRejectSnap(t, s, beforeEntries, beforeAccounts, beforeLocal, beforeRC)
127		assertValidSubmitEvictsQ1(t, s, beforeLocal, beforeRC)
128	}
129	
130	// 满池时签名有效但已到期（到期轮次不大于当前轮次）的全新交易必须返回
131	// tx-expired，而不是 pool-full；到期轮次恰好等于当前轮次也属于拒绝范围。
132	// 拒绝不挤出任何交易，之后合法交易仍按原有容量规则入池并挤出 q1。
133	func TestFullPoolRejectsExpired(t *testing.T) {
134		s := newCapProtectScene(t)
135		n := s.n
136		beforeEntries, beforeAccounts, beforeLocal, beforeRC := s.snapshots(t)
137	
138		// 到期轮次恰好等于当前轮次 1：拒绝。
139		expiredEqual := NewTransaction(s.keys[4].priv, 1, []byte("expired-equal"), 51, 1)
140		if !expiredEqual.Verify() {
141			t.Fatal("test setup: signature must be valid")
142		}
143		assertRejectedUnknown(t, n, expiredEqual, ReasonExpired)
144	
145		// 到期轮次小于当前轮次：同样拒绝。
146		expiredBefore := NewTransaction(s.keys[4].priv, 1, []byte("expired-before"), 51, 0)
147		assertRejectedUnknown(t, n, expiredBefore, ReasonExpired)
148	
149		fullPoolRejectSnap(t, s, beforeEntries, beforeAccounts, beforeLocal, beforeRC)
150		assertValidSubmitEvictsQ1(t, s, beforeLocal, beforeRC)
151	}
152

