1	package consensus
2	
3	import "testing"
4	
5	// 回归保障：交易提交会永久保留“曾被接受”的历史，即使交易后来已退出交易池
6	// （被替换 replaced 或进入到期轮次失效 expired）。重复判定以交易标识为唯一准据：
7	// 退出池不等于从未被接受；同一发送者加同一序号也不等于同一笔交易。
8	// 本文件沿用既有 Go 库入口（Submit/Tx/Account/EndRound）、既有拒绝原因
9	// （duplicate-transaction、fee-not-higher、tx-expired）与既有接收规则，
10	// 不引入任何新行为，只锁定这些既有结果。
11	
12	// 排队交易被同发送者同序号、费用严格更高的新交易替换后，按原始内容和签名
13	// 重新提交旧交易：必须返回 duplicate-transaction 而不是 fee-not-higher，
14	// 旧交易不能重新入池，两条记录与账户待处理列表均保持替换后的样子。
15	func TestResubmitReplacedHistoryReturnsDuplicate(t *testing.T) {
16		keys := genKeys(t, 4)
17		n, _ := newTestNode(t, keys, 10)
18	
19		// 旧交易先被接受，再被费用严格更高的同发送者同序号交易替换。
20		old := NewTransaction(keys[0].priv, 1, []byte("old-tx"), 1, 100)
21		if _, err := n.Submit(old); err != nil {
22			t.Fatal(err)
23		}
24		oldID := old.ID()
25		newTx := NewTransaction(keys[0].priv, 1, []byte("new-tx"), 5, 100)
26		rep, err := n.Submit(newTx)
27		if err != nil {
28			t.Fatal(err)
29		}
30		newID := newTx.ID()
31		if rep.ReplacedID != oldID || rep.TxID != newID {
32			t.Fatalf("setup replacement result wrong: %+v", rep)
33		}
34	
35		// 记录重投前的全局状态，拒绝操作不得改动它们。
36		entriesBefore := len(n.st.Entries)
37		roundBefore := n.CurrentRound()
38		heightBefore := n.Height()
39	
40		// 按最初被接受时的发送者、序号、内容、费用、到期轮次与签名原样重建。
41		// Ed25519 签名确定，逐字节相同的输入必须得到同一交易标识。
42		replay := NewTransaction(keys[0].priv, 1, []byte("old-tx"), 1, 100)
43		if replay.ID() != oldID {
44			t.Fatalf("test setup: byte-identical replay id %s != original %s", replay.ID(), oldID)
45		}
46		res, err := n.Submit(replay)
47		if err == nil {
48			t.Fatalf("resubmit of replaced tx must be rejected, got result %+v", res)
49		}
50		if got := reason(err); got != ReasonDuplicate {
51			t.Fatalf("resubmit replaced tx reason = %q, want %s (must not be %s)",
52				got, ReasonDuplicate, ReasonLowFee)
53		}
54		// 拒绝结果不得携带任何成功接收或再次替换的信息。
55		if res != nil {
56			t.Fatalf("rejected submit must return nil result, got %+v", res)
57		}
58	
59		// 拒绝本身不新增记录、不推进轮次、不生成确认块。
60		if len(n.st.Entries) != entriesBefore {
61			t.Fatalf("entries changed %d -> %d after rejected resubmit", entriesBefore, len(n.st.Entries))
62		}
63		if n.CurrentRound() != roundBefore || n.Height() != heightBefore {
64			t.Fatalf("round/height changed: %d/%d, want %d/%d",
65				n.CurrentRound(), n.Height(), roundBefore, heightBefore)
66		}
67		if blk, ok := n.LatestBlock(); ok {
68			t.Fatalf("rejected resubmit must not confirm a block, got %+v", blk)
69		}
70	
71		// 旧记录仍显示 replaced，替换关联仍指向原来接受的新交易，完整内容保留。
72		oldInfo, err := n.Tx(oldID)
73		if err != nil {
74			t.Fatal(err)
75		}
76		if oldInfo.Status != StatusReplaced || oldInfo.ReplacedBy != newID {
77			t.Fatalf("old record = status %s replacedBy %s, want replaced/%s",
78				oldInfo.Status, oldInfo.ReplacedBy, newID)
79		}
80		assertTxMatches(t, oldInfo.Tx, old)
81	
82		// 旧交易不能重新进入池：该账户序号 1 的当前交易仍只能是新交易。
83		if cur := n.st.Pool[old.SenderHex()][1]; cur != newID {
84			t.Fatalf("pool slot sender/seq1 = %s, want %s; old tx must not re-enter pool", cur, newID)
85		}
86	
87		// 新交易的内容与排队状态保持不变，也没有产生新的替换关联。
88		newInfo, err := n.Tx(newID)
89		if err != nil {
90			t.Fatal(err)
91		}
92		if newInfo.Status != StatusQueued || newInfo.ReplacedBy != "" {
93			t.Fatalf("new record changed: status=%s replacedBy=%q, want queued/empty",
94				newInfo.Status, newInfo.ReplacedBy)
95		}
96		assertTxMatches(t, newInfo.Tx, newTx)
97	
98		// 账户待处理列表仍是替换后的唯一一笔：新交易，等待打包。
99		acct := n.Account(keys[0].pub)
100		if acct.ConfirmedSequence != 0 || len(acct.Pending) != 1 {
101			t.Fatalf("account pending changed: %+v", acct)
102		}
103		p := acct.Pending[0]
104		if p.ID != newID || p.Status != StatusQueued || p.Note != "waiting-pack" {
105			t.Fatalf("account pending entry wrong: %+v", p)
106		}
107	
108		// 对照：同发送者同序号但标识不同的另一笔交易（费用仍低于当前交易）
109		// 必须走 fee-not-higher 而非 duplicate，且不留任何历史——
110		// 重复判据是交易标识，不是“发送者+序号”。
111		other := NewTransaction(keys[0].priv, 1, []byte("other-tx"), 3, 100)
112		if other.ID() == oldID || other.ID() == newID {
113			t.Fatal("test setup: distinct content must yield a distinct id")
114		}
115		if _, err := n.Submit(other); reason(err) != ReasonLowFee {
116			t.Fatalf("distinct-id same-sender/seq tx reason = %v, want %s", err, ReasonLowFee)
117		}
118		if _, err := n.Tx(other.ID()); reason(err) != ReasonUnknownTx {
119			t.Fatalf("fee-rejected distinct tx reason = %v, want %s (no history kept)", err, ReasonUnknownTx)
120		}
121		if len(n.st.Entries) != entriesBefore {
122			t.Fatalf("entries changed after control rejection: %d -> %d", entriesBefore, len(n.st.Entries))
123		}
124	}
125	
126	// 因进入到期轮次而失效的交易，再次按原样提交时，即使其到期轮次已不大于
127	// 当前轮次，仍必须返回 duplicate-transaction 而不是 tx-expired。历史记录、
128	// 账户待处理列表与已确认序号均不因此变化，拒绝操作不留任何副作用。
129	func TestResubmitExpiredHistoryReturnsDuplicate(t *testing.T) {
130		keys := genKeys(t, 4)
131		n, _ := newTestNode(t, keys, 10)
132	
133		// 第 1 轮接受到期轮次为 2 的交易。
134		old := NewTransaction(keys[0].priv, 1, []byte("expiring-tx"), 1, 2)
135		if _, err := n.Submit(old); err != nil {
136			t.Fatal(err)
137		}
138		oldID := old.ID()
139	
140		// 结束第 1 轮进入第 2 轮：expiry 2 <= round 2，交易失效并退出池。
141		round, err := n.EndRound()
142		if err != nil || round != 2 {
143			t.Fatalf("EndRound = %d, %v; want round 2", round, err)
144		}
145		info, err := n.Tx(oldID)
146		if err != nil {
147			t.Fatal(err)
148		}
149		if info.Status != StatusExpired {
150			t.Fatalf("setup: status = %s, want expired", info.Status)
151		}
152	
153		entriesBefore := len(n.st.Entries)
154	
155		// 原样重建并重投：六字段与签名均与最初被接受时一致，标识因此相同。
156		replay := NewTransaction(keys[0].priv, 1, []byte("expiring-tx"), 1, 2)
157		if replay.ID() != oldID {
158			t.Fatalf("test setup: byte-identical replay id %s != original %s", replay.ID(), oldID)
159		}
160		res, err := n.Submit(replay)
161		if err == nil {
162			t.Fatalf("resubmit of expired history must be rejected, got result %+v", res)
163		}
164		if got := reason(err); got != ReasonDuplicate {
165			t.Fatalf("resubmit expired tx reason = %q, want %s (must not be %s even though expiry %d <= round %d)",
166				got, ReasonDuplicate, ReasonExpired, old.Expiry, n.CurrentRound())
167		}
168		if res != nil {
169			t.Fatalf("rejected submit must return nil result, got %+v", res)
170		}
171	
172		// 拒绝操作本身：不新增交易记录、不改变当前轮次、不生成确认块。
173		if len(n.st.Entries) != entriesBefore {
174			t.Fatalf("entries changed %d -> %d after rejected resubmit", entriesBefore, len(n.st.Entries))
175		}
176		if n.CurrentRound() != 2 || n.Height() != 0 {
177			t.Fatalf("round/height changed: %d/%d, want 2/0", n.CurrentRound(), n.Height())
178		}
179		if blk, ok := n.LatestBlock(); ok {
180			t.Fatalf("rejected resubmit must not confirm a block, got %+v", blk)
181		}
182	
183		// 原记录继续显示 expired，完整交易内容与签名保留，不带区块或替换关联。
184		info, err = n.Tx(oldID)
185		if err != nil {
186			t.Fatal(err)
187		}
188		if info.Status != StatusExpired || info.BlockID != "" || info.BlockHeight != 0 || info.ReplacedBy != "" {
189			t.Fatalf("expired record wrong: %+v", info)
190		}
191		assertTxMatches(t, info.Tx, old)
192	
193		// 账户待处理列表中不能重新出现它，已确认序号也不因此推进。
194		acct := n.Account(keys[0].pub)
195		if acct.ConfirmedSequence != 0 || len(acct.Pending) != 0 {
196			t.Fatalf("expired tx must not reappear pending nor advance sequence: %+v", acct)
197		}
198	}
199	
200	// 对照：一笔从未被接受、提交时就已经到期的交易返回 tx-expired，
201	// 并且查询不到任何历史记录。它与上面的历史旧交易可以同发送者同序号，
202	// 区别仅在交易标识（内容与签名不同）。
203	func TestNeverAcceptedExpiredTxRejectedWithoutHistory(t *testing.T) {
204		keys := genKeys(t, 4)
205		n, _ := newTestNode(t, keys, 10)
206	
207		// 先制造一条 expired 历史，保证“历史交易”与“从未接受交易”同场可比。
208		hist := NewTransaction(keys[0].priv, 1, []byte("accepted-then-expired"), 1, 2)
209		if _, err := n.Submit(hist); err != nil {
210			t.Fatal(err)
211		}
212		if _, err := n.EndRound(); err != nil {
213			t.Fatal(err)
214		}
215		if info, _ := n.Tx(hist.ID()); info.Status != StatusExpired {
216			t.Fatalf("setup: history status = %s, want expired", info.Status)
217		}
218		entriesBefore := len(n.st.Entries)
219	
220		// 同发送者同序号、但内容与签名全新的另一笔交易：当前为第 2 轮，提交即到期。
221		fresh := NewTransaction(keys[0].priv, 1, []byte("never-accepted"), 1, 2)
222		if fresh.ID() == hist.ID() {
223			t.Fatal("test setup: fresh tx must have a distinct id from history tx")
224		}
225		res, err := n.Submit(fresh)
226		if err == nil {
227			t.Fatalf("already-expired new tx must be rejected, got result %+v", res)
228		}
229		if got := reason(err); got != ReasonExpired {
230			t.Fatalf("never-accepted expired tx reason = %q, want %s", got, ReasonExpired)
231		}
232		if res != nil {
233			t.Fatalf("rejected submit must return nil result, got %+v", res)
234		}
235	
236		// 从未被接受：按标识查询不到历史，条目数不增加。
237		if _, err := n.Tx(fresh.ID()); reason(err) != ReasonUnknownTx {
238			t.Fatalf("fresh expired tx lookup reason = %v, want %s", err, ReasonUnknownTx)
239		}
240		if len(n.st.Entries) != entriesBefore {
241			t.Fatalf("entries changed %d -> %d; expired rejection keeps no history",
242				entriesBefore, len(n.st.Entries))
243		}
244	
245		// 既有 expired 历史不受这次拒绝影响。
246		histInfo, err := n.Tx(hist.ID())
247		if err != nil {
248			t.Fatal(err)
249		}
250		if histInfo.Status != StatusExpired {
251			t.Fatalf("history record changed: status = %s, want expired", histInfo.Status)
252		}
253	
254		// 同场再验一次分野：历史交易原样重投是 duplicate，而非 tx-expired。
255		replay := NewTransaction(keys[0].priv, 1, []byte("accepted-then-expired"), 1, 2)
256		if replay.ID() != hist.ID() {
257			t.Fatalf("test setup: replay id %s != history id %s", replay.ID(), hist.ID())
258		}
259		if _, err := n.Submit(replay); reason(err) != ReasonDuplicate {
260			t.Fatalf("history replay reason = %v, want %s", err, ReasonDuplicate)
261		}
262	}
263	
264	// 过期只结束旧交易的有效性，并不占用该账户尚未确认的序号。同发送者同序号
265	// 重新签署一笔到期轮次晚于当前轮次的新交易，只要符合既有接收条件就正常入队；
266	// 它不是替换（即使新费用更低也不能按 fee-not-higher 拒绝），旧记录保持 expired。
267	func TestExpiryFreesSequenceForFreshlySignedTx(t *testing.T) {
268		keys := genKeys(t, 4)
269		n, _ := newTestNode(t, keys, 10)
270	
271		old := NewTransaction(keys[0].priv, 1, []byte("old-expired"), 2, 2)
272		if _, err := n.Submit(old); err != nil {
273			t.Fatal(err)
274		}
275		oldID := old.ID()
276		if _, err := n.EndRound(); err != nil {
277			t.Fatal(err)
278		}
279		if info, _ := n.Tx(oldID); info.Status != StatusExpired {
280			t.Fatalf("setup: status = %s, want expired", info.Status)
281		}
282		entriesBefore := len(n.st.Entries)
283	
284		// 同发送者同序号重新签署：新内容、费用甚至低于旧交易、到期轮次晚于当前轮次。
285		renewed := NewTransaction(keys[0].priv, 1, []byte("renewed"), 1, 10)
286		if renewed.ID() == oldID {
287			t.Fatal("test setup: renewed tx must have a distinct id")
288		}
289		if n.CurrentRound() >= renewed.Expiry {
290			t.Fatalf("test setup: renewed expiry %d must be greater than current round %d",
291				renewed.Expiry, n.CurrentRound())
292		}
293		res, err := n.Submit(renewed)
294		if err != nil {
295			t.Fatalf("freshly signed tx for expired sequence must be accepted: %v", err)
296		}
297		newID := renewed.ID()
298		// 旧交易早已退出池：这是一次全新接收，不是替换，也没有挤出任何交易。
299		if res.TxID != newID || res.ReplacedID != "" || res.EvictedID != "" {
300			t.Fatalf("renewed submit result wrong: %+v", res)
301		}
302	
303		// 仅新增新交易一条记录；旧记录仍为 expired，替换关联保持为空。
304		if len(n.st.Entries) != entriesBefore+1 {
305			t.Fatalf("entries changed %d -> %d, want %d", entriesBefore, len(n.st.Entries), entriesBefore+1)
306		}
307		oldInfo, err := n.Tx(oldID)
308		if err != nil {
309			t.Fatal(err)
310		}
311		if oldInfo.Status != StatusExpired || oldInfo.ReplacedBy != "" {
312			t.Fatalf("old record changed: status=%s replacedBy=%q, want expired/empty",
313				oldInfo.Status, oldInfo.ReplacedBy)
314		}
315		// 新交易按自己的标识可查，内容与签名完整，处于排队状态。
316		newInfo, err := n.Tx(newID)
317		if err != nil {
318			t.Fatal(err)
319		}
320		if newInfo.Status != StatusQueued {
321			t.Fatalf("renewed tx status = %s, want queued", newInfo.Status)
322		}
323		assertTxMatches(t, newInfo.Tx, renewed)
324	
325		// 账户待处理列表中，序号 1 对应的是有效的新交易；旧 expired 交易不出现。
326		acct := n.Account(keys[0].pub)
327		if acct.ConfirmedSequence != 0 || acct.Gap != 0 || len(acct.Pending) != 1 {
328			t.Fatalf("account wrong after renewal: %+v", acct)
329		}
330		p := acct.Pending[0]
331		if p.ID != newID || p.Status != StatusQueued || p.Note != "waiting-pack" {
332			t.Fatalf("pending entry wrong: %+v", p)
333		}
334	
335		// 正常进入排队即可被下一轮打包，证明它走的是既有接收规则。
336		prop, err := n.Propose()
337		if err != nil {
338			t.Fatal(err)
339		}
340		if prop.Round != 2 || len(prop.TxIDs) != 1 || prop.TxIDs[0] != newID {
341			t.Fatalf("renewed tx should pack in round 2, got %+v", prop)
342		}
343	}
344

